ALTER TABLE endi.f2_lactancia DROP CONSTRAINT IF EXISTS ck_f2_lactancia_identificadores RESTRICT;
ALTER TABLE endi.f2_salud_ninez DROP CONSTRAINT IF EXISTS ck_f2_salud_ninez_identificadores RESTRICT;
ALTER TABLE endi.f3_desarrollo_inf DROP CONSTRAINT IF EXISTS ck_f3_desarrollo_inf_identificadores RESTRICT;
ALTER TABLE endi.f1_personas DROP CONSTRAINT IF EXISTS ck_f1_personas_mef_persona RESTRICT;
ALTER TABLE endi.f2_lactancia DROP CONSTRAINT IF EXISTS ck_f2_lactancia_mef_per RESTRICT;
ALTER TABLE endi.f2_salud_ninez DROP CONSTRAINT IF EXISTS ck_f2_salud_ninez_mef_per RESTRICT;
ALTER TABLE endi.f2_salud_ninez DROP CONSTRAINT IF EXISTS ck_f2_salud_ninez_hijo_orden RESTRICT;
ALTER TABLE endi.f3_desarrollo_inf DROP CONSTRAINT IF EXISTS ck_f3_desarrollo_inf_cuidador_distinto RESTRICT;
ALTER TABLE endi.f1_hogar DROP CONSTRAINT IF EXISTS pk_f1_hogar RESTRICT;
ALTER TABLE endi.f1_personas DROP CONSTRAINT IF EXISTS pk_f1_personas RESTRICT;
ALTER TABLE endi.f2_mef DROP CONSTRAINT IF EXISTS pk_f2_mef RESTRICT;
ALTER TABLE endi.f2_lactancia DROP CONSTRAINT IF EXISTS pk_f2_lactancia RESTRICT;
ALTER TABLE endi.f2_salud_ninez DROP CONSTRAINT IF EXISTS pk_f2_salud_ninez RESTRICT;
ALTER TABLE endi.f3_desarrollo_inf DROP CONSTRAINT IF EXISTS pk_f3_desarrollo_inf RESTRICT;
ALTER TABLE endi.f2_salud_ninez ADD COLUMN IF NOT EXISTS id_per_miembro TEXT GENERATED ALWAYS AS (CASE WHEN right(id_per::text, 2) = '77'::text THEN NULL::text ELSE id_per::text END) STORED;
ALTER TABLE endi.f1_hogar ALTER COLUMN id_upm SET NOT NULL, ALTER COLUMN id_viv SET NOT NULL, ALTER COLUMN id_hogar SET NOT NULL;
ALTER TABLE endi.f1_personas ALTER COLUMN id_upm SET NOT NULL, ALTER COLUMN id_viv SET NOT NULL, ALTER COLUMN id_hogar SET NOT NULL, ALTER COLUMN id_per SET NOT NULL;
