ALTER TABLE endi.f2_lactancia ALTER COLUMN id_upm SET NOT NULL, ALTER COLUMN id_viv SET NOT NULL, ALTER COLUMN id_hogar SET NOT NULL, ALTER COLUMN id_per SET NOT NULL, ALTER COLUMN id_mef SET NOT NULL, ALTER COLUMN id_mef_per SET NOT NULL;
ALTER TABLE endi.f2_salud_ninez ALTER COLUMN id_upm SET NOT NULL, ALTER COLUMN id_viv SET NOT NULL, ALTER COLUMN id_hogar SET NOT NULL, ALTER COLUMN id_hijo_ord SET NOT NULL, ALTER COLUMN id_per SET NOT NULL, ALTER COLUMN id_mef SET NOT NULL, ALTER COLUMN id_mef_per SET NOT NULL, ALTER COLUMN ord_hijo SET NOT NULL;
ALTER TABLE endi.f3_desarrollo_inf ALTER COLUMN id_upm SET NOT NULL, ALTER COLUMN id_viv SET NOT NULL, ALTER COLUMN id_hogar SET NOT NULL, ALTER COLUMN id_per SET NOT NULL, ALTER COLUMN id_cuid SET NOT NULL;
