ALTER TABLE endi.f3_desarrollo_inf ADD CONSTRAINT uq_f3_desarrollo_inf_cuidador UNIQUE (id_cuid);
ALTER TABLE endi.f1_hogar ADD CONSTRAINT ck_f1_hogar_identificadores CHECK (id_upm ~ '^[0-9]{10}$' AND id_viv ~ '^[0-9]{12}$' AND id_hogar ~ '^[0-9]{14}$' AND left(id_viv, 10) = id_upm AND left(id_hogar, 12) = id_viv);
ALTER TABLE endi.f1_personas ADD CONSTRAINT ck_f1_personas_identificadores CHECK (id_upm ~ '^[0-9]{10}$' AND id_viv ~ '^[0-9]{12}$' AND id_hogar ~ '^[0-9]{14}$' AND left(id_viv, 10) = id_upm AND left(id_hogar, 12) = id_viv AND (id_per IS NULL OR (id_per ~ '^[0-9]{16}$' AND left(id_per, 14) = id_hogar)) AND (id_mef IS NULL OR (id_mef ~ '^[0-9]{16}$' AND left(id_mef, 14) = id_hogar)));
ALTER TABLE endi.f2_mef ADD CONSTRAINT ck_f2_mef_identificadores CHECK (id_upm ~ '^[0-9]{10}$' AND id_viv ~ '^[0-9]{12}$' AND id_hogar ~ '^[0-9]{14}$' AND left(id_viv, 10) = id_upm AND left(id_hogar, 12) = id_viv AND (id_mef IS NULL OR (id_mef ~ '^[0-9]{16}$' AND left(id_mef, 14) = id_hogar)));
ALTER TABLE endi.f2_lactancia ADD CONSTRAINT ck_f2_lactancia_identificadores CHECK (id_upm ~ '^[0-9]{10}$' AND id_viv ~ '^[0-9]{12}$' AND id_hogar ~ '^[0-9]{14}$' AND left(id_viv, 10) = id_upm AND left(id_hogar, 12) = id_viv AND (id_per IS NULL OR (id_per ~ '^[0-9]{16}$' AND left(id_per, 14) = id_hogar)) AND (id_mef IS NULL OR (id_mef ~ '^[0-9]{16}$' AND left(id_mef, 14) = id_hogar)));
ALTER TABLE endi.f2_salud_ninez ADD CONSTRAINT ck_f2_salud_ninez_identificadores CHECK (id_upm ~ '^[0-9]{10}$' AND id_viv ~ '^[0-9]{12}$' AND id_hogar ~ '^[0-9]{14}$' AND left(id_viv, 10) = id_upm AND left(id_hogar, 12) = id_viv AND (id_per IS NULL OR (id_per ~ '^[0-9]{16}$' AND left(id_per, 14) = id_hogar)) AND (id_mef IS NULL OR (id_mef ~ '^[0-9]{16}$' AND left(id_mef, 14) = id_hogar)));
ALTER TABLE endi.f3_desarrollo_inf ADD CONSTRAINT ck_f3_desarrollo_inf_identificadores CHECK (id_upm ~ '^[0-9]{10}$' AND id_viv ~ '^[0-9]{12}$' AND id_hogar ~ '^[0-9]{14}$' AND left(id_viv, 10) = id_upm AND left(id_hogar, 12) = id_viv AND (id_per IS NULL OR (id_per ~ '^[0-9]{16}$' AND left(id_per, 14) = id_hogar)) AND (id_cuid IS NULL OR (id_cuid ~ '^[0-9]{16}$' AND left(id_cuid, 14) = id_hogar)));
ALTER TABLE endi.f1_personas ADD CONSTRAINT ck_f1_personas_mef_persona CHECK (id_mef IS NULL OR id_mef = id_per);
ALTER TABLE endi.f2_lactancia ADD CONSTRAINT ck_f2_lactancia_mef_per CHECK (id_mef_per = id_mef || right(id_per, 2));
ALTER TABLE endi.f2_salud_ninez ADD CONSTRAINT ck_f2_salud_ninez_mef_per CHECK (id_mef_per = id_mef || right(id_per, 2));
ALTER TABLE endi.f2_salud_ninez ADD CONSTRAINT ck_f2_salud_ninez_hijo_orden CHECK (ord_hijo IN ('01', '02') AND id_hijo_ord = id_mef_per || ord_hijo);
ALTER TABLE endi.f3_desarrollo_inf ADD CONSTRAINT ck_f3_desarrollo_inf_cuidador_distinto CHECK (id_cuid <> id_per);
ALTER TABLE endi.f1_personas ADD CONSTRAINT fk_f1_personas_hogar FOREIGN KEY (id_hogar) REFERENCES endi.f1_hogar (id_hogar) ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE endi.f2_mef ADD CONSTRAINT fk_f2_mef_hogar FOREIGN KEY (id_hogar) REFERENCES endi.f1_hogar (id_hogar) ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE endi.f2_mef ADD CONSTRAINT fk_f2_mef_persona_mef FOREIGN KEY (id_mef) REFERENCES endi.f1_personas (id_mef) ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE endi.f2_lactancia ADD CONSTRAINT fk_f2_lactancia_hogar FOREIGN KEY (id_hogar) REFERENCES endi.f1_hogar (id_hogar) ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE endi.f2_lactancia ADD CONSTRAINT fk_f2_lactancia_madre FOREIGN KEY (id_mef) REFERENCES endi.f2_mef (id_mef) ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE endi.f2_lactancia ADD CONSTRAINT fk_f2_lactancia_persona FOREIGN KEY (id_per) REFERENCES endi.f1_personas (id_per) ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE endi.f2_salud_ninez ADD CONSTRAINT fk_f2_salud_ninez_hogar FOREIGN KEY (id_hogar) REFERENCES endi.f1_hogar (id_hogar) ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE endi.f2_salud_ninez ADD CONSTRAINT fk_f2_salud_ninez_madre FOREIGN KEY (id_mef) REFERENCES endi.f2_mef (id_mef) ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE endi.f2_salud_ninez ADD CONSTRAINT fk_f2_salud_ninez_persona_miembro FOREIGN KEY (id_per_miembro) REFERENCES endi.f1_personas (id_per) ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE endi.f3_desarrollo_inf ADD CONSTRAINT fk_f3_desarrollo_inf_hogar FOREIGN KEY (id_hogar) REFERENCES endi.f1_hogar (id_hogar) ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE endi.f3_desarrollo_inf ADD CONSTRAINT fk_f3_desarrollo_inf_persona FOREIGN KEY (id_per) REFERENCES endi.f1_personas (id_per) ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE endi.f3_desarrollo_inf ADD CONSTRAINT fk_f3_desarrollo_inf_cuidador FOREIGN KEY (id_cuid) REFERENCES endi.f1_personas (id_per) ON UPDATE NO ACTION ON DELETE RESTRICT;
CREATE INDEX IF NOT EXISTS ix_f1_personas_id_hogar ON endi.f1_personas (id_hogar);
CREATE INDEX IF NOT EXISTS ix_f2_mef_id_hogar ON endi.f2_mef (id_hogar);
CREATE INDEX IF NOT EXISTS ix_f2_lactancia_id_hogar ON endi.f2_lactancia (id_hogar);
CREATE INDEX IF NOT EXISTS ix_f2_salud_ninez_id_hogar ON endi.f2_salud_ninez (id_hogar);
COMMENT ON COLUMN endi.f2_salud_ninez.id_per_miembro IS 'Derivada ENDI: NULL para id_per terminado en 77 (no miembro); conserva id_per original y habilita FK a Personas.';
COMMIT;
